1	package command
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math/big"
10		"os"
11		"path/filepath"
12		"strconv"
13		"strings"
14	
15		"gopkg.in/yaml.v3"
16	)
17	
18	// This file adds a configuration-file entry point to the parser:
19	// (*Parser).ParseConfigFiles loads a set of JSON or YAML files, merges
20	// them into a single config layer, and hands the result to the existing
21	// ParseWithSources machinery, so option type conversion and required
22	// checks keep their established semantics.
23	
24	// Sentinel errors describing configuration-file failures. Each is wrapped
25	// in a *ConfigError that carries the offending path; callers distinguish
26	// classes with errors.Is and recover the path with errors.As.
27	var (
28		// ErrUnsupportedConfigFormat indicates a file whose extension is not
29		// .json, .yaml or .yml (matched case-insensitively).
30		ErrUnsupportedConfigFormat = errors.New("command: unsupported config file format")
31	
32		// ErrConfigIO indicates a config file that could not be opened or
33		// read.
34		ErrConfigIO = errors.New("command: config file I/O error")
35	
36		// ErrInvalidConfig indicates a config file whose syntax or structure
37		// is not a valid configuration: a non-object root, an object value, a
38		// nested array, a null array element, or a duplicated top-level key.
39		ErrInvalidConfig = errors.New("command: invalid config file")
40	)
41	
42	// ConfigError wraps one of the configuration-file sentinels and identifies
43	// the file that failed.
44	type ConfigError struct {
45		// Path is the config file path exactly as passed to ParseConfigFiles.
46		Path string
47	
48		kind error
49		msg  string
50	}
51	
52	func (e *ConfigError) Error() string { return e.msg }
53	func (e *ConfigError) Unwrap() error { return e.kind }
54	
55	// ParseConfigFiles decodes args with additional value layers loaded from
56	// the given JSON or YAML configuration files. Precedence is fixed,
57	// command line first: args, then environ, then the files in path order
58	// (a later file outranks an earlier one), then the option's Default.
59	//
60	// Each file's format is selected by its extension, case-insensitively:
61	// .json, .yaml or .yml. The top level of a file must be an object whose
62	// keys correspond to Option.ConfigKey values; unknown keys are ignored.
63	// A scalar value supplies one raw value and an array of scalars supplies
64	// several in order: strings are kept verbatim, booleans are canonicalized
65	// to "true" or "false", and numbers are rendered as decimal text. A null
66	// value or an empty array clears the key: values from lower-priority
67	// files are removed and the key is no longer supplied by the config
68	// layer, so the option falls back to lower layers or its default. When
69	// the same key appears in several files the higher-priority file
70	// replaces the whole value group; keys a file does not mention are
71	// inherited from lower-priority files.
72	//
73	// Object values, nested arrays, null array elements, duplicated
74	// top-level keys and non-object roots are invalid configurations. Every
75	// file is fully read and structurally validated before any merging
76	// happens: on the first failure the returned result is nil and the error
77	// is a *ConfigError wrapping ErrUnsupportedConfigFormat, ErrConfigIO or
78	// ErrInvalidConfig, with no partial merge handed to the caller.
79	//
80	// After merging, conversion and required checks are exactly those of
81	// ParseWithSources: an effective config value that fails type conversion
82	// yields a *ParseError wrapping ErrInvalidValue with SourceConfig, while
83	// values shadowed by a higher layer are never converted (their files
84	// must still be syntactically and structurally valid).
85	//
86	// ParseConfigFiles never reads the process environment, does not modify
87	// or retain args, paths or environ, produces no output, and is safe for
88	// concurrent use on a shared Parser.
89	func (p *Parser) ParseConfigFiles(args []string, paths []string, environ map[string]string) (*Result, error) {
90		if len(paths) == 0 {
91			return p.ParseWithSources(args, nil, environ)
92		}
93	
94		// Phase 1: read and validate every file. Nothing is merged until all
95		// of them have succeeded, so a failure cannot leak a partial result.
96		files := make([]map[string][]string, len(paths))
97		for i, path := range paths {
98			entries, err := loadConfigFile(path)
99			if err != nil {
100				return nil, err
101			}
102			files[i] = entries
103		}
104	
105		// Phase 2: merge in ascending priority order. A non-empty group
106		// replaces the lower-priority group wholesale; an empty group (null
107		// or empty array) removes the key from the config layer entirely.
108		merged := make(map[string][]string)
109		for _, entries := range files {
110			for key, values := range entries {
111				if len(values) == 0 {
112					delete(merged, key)
113					continue
114				}
115				merged[key] = values
116			}
117		}
118	
119		// Phase 3: reuse the established layering, conversion and required
120		// semantics.
121		return p.ParseWithSources(args, merged, environ)
122	}
123	
124	// loadConfigFile reads and validates one configuration file, returning
125	// its top-level entries as raw value groups. A key mapped to an empty
126	// slice was explicitly cleared (null or empty array).
127	func loadConfigFile(path string) (map[string][]string, error) {
128		var parse func([]byte) (map[string][]string, error)
129		switch strings.ToLower(filepath.Ext(path)) {
130		case ".json":
131			parse = parseJSONConfig
132		case ".yaml", ".yml":
133			parse = parseYAMLConfig
134		default:
135			return nil, &ConfigError{Path: path, kind: ErrUnsupportedConfigFormat,
136				msg: fmt.Sprintf("command: unsupported config file format %q", path)}
137		}
138	
139		data, err := os.ReadFile(path)
140		if err != nil {
141			return nil, &ConfigError{Path: path, kind: ErrConfigIO,
142				msg: fmt.Sprintf("command: cannot read config file %q: %v", path, err)}
143		}
144	
145		entries, err := parse(data)
146		if err != nil {
147			return nil, &ConfigError{Path: path, kind: ErrInvalidConfig,
148				msg: fmt.Sprintf("command: invalid config file %q: %v", path, err)}
149		}
150		return entries, nil
151	}
152	
153	// parseJSONConfig decodes one JSON configuration document. The decoder is
154	// driven token by token so that duplicated top-level keys and disallowed
155	// value shapes are reported instead of silently accepted.
156	func parseJSONConfig(data []byte) (map[string][]string, error) {
157		dec := json.NewDecoder(bytes.NewReader(data))
158		dec.UseNumber()
159	
160		tok, err := dec.Token()
161		if err != nil {
162			return nil, fmt.Errorf("syntax error: %v", err)
163		}
164		if d, ok := tok.(json.Delim); !ok || d != '{' {
165			return nil, errors.New("top level must be an object")
166		}
167	
168		entries := make(map[string][]string)
169		for dec.More() {
170			ktok, err := dec.Token()
171			if err != nil {
172				return nil, fmt.Errorf("syntax error: %v", err)
173			}
174			key, ok := ktok.(string)
175			if !ok {
176				return nil, fmt.Errorf("expected object key, got %v", ktok)
177			}
178			if _, dup := entries[key]; dup {
179				return nil, fmt.Errorf("duplicate top-level key %q", key)
180			}
181	
182			vtok, err := dec.Token()
183			if err != nil {
184				return nil, fmt.Errorf("syntax error: %v", err)
185			}
186			if d, ok := vtok.(json.Delim); ok {
187				if d != '[' {
188					return nil, fmt.Errorf("key %q: object values are not allowed", key)
189				}
190				values, err := jsonArray(dec, key)
191				if err != nil {
192					return nil, err
193				}
194				entries[key] = values
195				continue
196			}
197			raw, isNull, err := jsonScalar(vtok)
198			if err != nil {
199				return nil, fmt.Errorf("key %q: %v", key, err)
200			}
201			if isNull {
202				entries[key] = nil
203				continue
204			}
205			entries[key] = []string{raw}
206		}
207		if _, err := dec.Token(); err != nil {
208			return nil, fmt.Errorf("syntax error: %v", err)
209		}
210		if _, err := dec.Token(); err != io.EOF {
211			return nil, errors.New("unexpected content after top-level object")
212		}
213		return entries, nil
214	}
215	
216	// jsonArray consumes one JSON array of scalars, including the closing
217	// delimiter. Nested arrays, objects and null elements are rejected.
218	func jsonArray(dec *json.Decoder, key string) ([]string, error) {
219		values := []string{}
220		for dec.More() {
221			tok, err := dec.Token()
222			if err != nil {
223				return nil, fmt.Errorf("syntax error: %v", err)
224			}
225			raw, isNull, err := jsonScalar(tok)
226			if err != nil {
227				return nil, fmt.Errorf("key %q: %v", key, err)
228			}
229			if isNull {
230				return nil, fmt.Errorf("key %q: null array elements are not allowed", key)
231			}
232			values = append(values, raw)
233		}
234		if _, err := dec.Token(); err != nil {
235			return nil, fmt.Errorf("syntax error: %v", err)
236		}
237		return values, nil
238	}
239	
240	// jsonScalar renders one JSON scalar token as a raw config value. A nil
241	// token is JSON null, reported via isNull; anything else (a delimiter) is
242	// a structural error.
243	func jsonScalar(tok any) (raw string, isNull bool, err error) {
244		switch v := tok.(type) {
245		case nil:
246			return "", true, nil
247		case string:
248			return v, false, nil
249		case bool:
250			return strconv.FormatBool(v), false, nil
251		case json.Number:
252			text, err := decimalText(string(v))
253			if err != nil {
254				return "", false, fmt.Errorf("invalid number %q", string(v))
255			}
256			return text, false, nil
257		default:
258			return "", false, errors.New("nested arrays and objects are not allowed")
259		}
260	}
261	
262	// parseYAMLConfig decodes one YAML configuration document into the same
263	// entry shape as parseJSONConfig. An empty file yields an empty object.
264	func parseYAMLConfig(data []byte) (map[string][]string, error) {
265		dec := yaml.NewDecoder(bytes.NewReader(data))
266		var doc yaml.Node
267		if err := dec.Decode(&doc); err != nil {
268			if err == io.EOF {
269				return map[string][]string{}, nil
270			}
271			return nil, fmt.Errorf("syntax error: %v", err)
272		}
273		var extra yaml.Node
274		if err := dec.Decode(&extra); err != io.EOF {
275			return nil, errors.New("multiple documents are not allowed")
276		}
277	
278		root := &doc
279		if root.Kind == yaml.DocumentNode {
280			root = root.Content[0]
281		}
282		if root.Kind != yaml.MappingNode {
283			return nil, errors.New("top level must be an object")
284		}
285	
286		entries := make(map[string][]string)
287		for i := 0; i < len(root.Content); i += 2 {
288			kn, vn := root.Content[i], resolveAlias(root.Content[i+1])
289			if kn.Kind != yaml.ScalarNode {
290				return nil, errors.New("non-scalar top-level keys are not allowed")
291			}
292			key := kn.Value
293			if _, dup := entries[key]; dup {
294				return nil, fmt.Errorf("duplicate top-level key %q", key)
295			}
296	
297			switch vn.Kind {
298			case yaml.ScalarNode:
299				raw, isNull, err := yamlScalar(vn)
300				if err != nil {
301					return nil, fmt.Errorf("key %q: %v", key, err)
302				}
303				if isNull {
304					entries[key] = nil
305					continue
306				}
307				entries[key] = []string{raw}
308			case yaml.SequenceNode:
309				values := []string{}
310				for _, item := range vn.Content {
311					item = resolveAlias(item)
312					if item.Kind != yaml.ScalarNode {
313						return nil, fmt.Errorf("key %q: nested arrays and objects are not allowed", key)
314					}
315					raw, isNull, err := yamlScalar(item)
316					if err != nil {
317						return nil, fmt.Errorf("key %q: %v", key, err)
318					}
