1	package command
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"reflect"
8		"strings"
9		"sync"
10		"testing"
11		"time"
12	)
13	
14	func boundParser(t *testing.T) *Parser {
15		t.Helper()
16		p, err := NewParser([]Option{
17			{Long: "host", Short: "h", Type: TypeString, Default: "localhost", ConfigKey: "host", EnvVar: "APP_HOST"},
18			{Long: "port", Short: "p", Type: TypeInt, Default: "8080", ConfigKey: "port", EnvVar: "APP_PORT"},
19			{Long: "timeout", Type: TypeDuration, ConfigKey: "timeout", EnvVar: "APP_TIMEOUT"},
20			{Long: "verbose", Short: "v", Type: TypeBool, ConfigKey: "verbose", EnvVar: "APP_VERBOSE"},
21			{Long: "tag", Type: TypeString, Repeatable: true, ConfigKey: "tags", EnvVar: "APP_TAG"},
22			{Long: "num", Type: TypeInt, Repeatable: true, ConfigKey: "nums"},
23			{Long: "need", Type: TypeString, Required: true, ConfigKey: "need", EnvVar: "APP_NEED"},
24		}, nil)
25		if err != nil {
26			t.Fatal(err)
27		}
28		return p
29	}
30	
31	func TestParseWithSourcesDefaults(t *testing.T) {
32		p := boundParser(t)
33		r, err := p.ParseWithSources([]string{"--need", "x"}, nil, map[string]string{"UNRELATED": "x"})
34		if err != nil {
35			t.Fatal(err)
36		}
37		if r.Source("host") != SourceDefault || r.String("host") != "localhost" {
38			t.Fatalf("host source=%v value=%q", r.Source("host"), r.String("host"))
39		}
40		if r.Source("port") != SourceDefault || r.Int("port") != 8080 {
41			t.Fatalf("port source=%v value=%d", r.Source("port"), r.Int("port"))
42		}
43		if r.Source("timeout") != SourceDefault || r.Duration("timeout") != 0 {
44			t.Fatalf("timeout source=%v", r.Source("timeout"))
45		}
46		if r.Source("unknown") != SourceNone {
47			t.Fatalf("unknown source = %v, want SourceNone", r.Source("unknown"))
48		}
49	}
50	
51	func TestSourcePrecedence(t *testing.T) {
52		p := boundParser(t)
53		config := map[string][]string{
54			"host":    {"cfg-host"},
55			"port":    {"9000"},
56			"timeout": {"700ms"},
57		}
58		environ := map[string]string{
59			"APP_HOST": "env-host",
60			"APP_PORT": "7000",
61		}
62		r, err := p.ParseWithSources([]string{"--host", "cli-host", "--need", "x"}, config, environ)
63		if err != nil {
64			t.Fatal(err)
65		}
66	
67		// Command line beats environment and config.
68		if r.Source("host") != SourceCommandLine || r.String("host") != "cli-host" {
69			t.Fatalf("host source=%v value=%q", r.Source("host"), r.String("host"))
70		}
71		// Environment beats config.
72		if r.Source("port") != SourceEnvironment || r.Int("port") != 7000 {
73			t.Fatalf("port source=%v value=%d", r.Source("port"), r.Int("port"))
74		}
75		// Config beats the default.
76		if r.Source("timeout") != SourceConfig || r.Duration("timeout") != 700*time.Millisecond {
77			t.Fatalf("timeout source=%v value=%v", r.Source("timeout"), r.Duration("timeout"))
78		}
79	
80		// Higher layers are never converted or mixed in when a higher layer
81		// supplies the option.
82		bad := map[string][]string{"port": {"not-a-number"}}
83		r2, err := p.ParseWithSources([]string{"--port", "1", "--need", "x"}, bad,
84			map[string]string{"APP_NEED": "y"})
85		if err != nil {
86			t.Fatalf("invalid lower-layer values must be ignored when covered: %v", err)
87		}
88		if r2.Int("port") != 1 || r2.Source("port") != SourceCommandLine {
89			t.Fatalf("port = %d source %v", r2.Int("port"), r2.Source("port"))
90		}
91	}
92	
93	func TestConfigMultipleValues(t *testing.T) {
94		p := boundParser(t)
95		config := map[string][]string{
96			"host": {"first", "middle", "last"},
97			"tags": {"a", "b", "c"},
98			// Earlier invalid values for a non-repeatable option are never
99			// reached: only the last element is taken.
100			"port": {"not-a-number", "6500"},
101		}
102		r, err := p.ParseWithSources([]string{"--need", "x"}, config, nil)
103		if err != nil {
104			t.Fatal(err)
105		}
106		if r.Source("host") != SourceConfig || r.String("host") != "last" {
107			t.Fatalf("host = %q source %v, want last config element", r.String("host"), r.Source("host"))
108		}
109		if r.Source("tag") != SourceConfig || !reflect.DeepEqual(r.Strings("tag"), []string{"a", "b", "c"}) {
110			t.Fatalf("tags = %v source %v", r.Strings("tag"), r.Source("tag"))
111		}
112		if r.Int("port") != 6500 {
113			t.Fatalf("port = %d, want last element 6500", r.Int("port"))
114		}
115	
116		// A bad last element fails non-repeatable conversion.
117		_, err = p.ParseWithSources([]string{"--need", "x"},
118			map[string][]string{"port": {"6500", "bad"}}, nil)
119		var pe *ParseError
120		if !errors.As(err, &pe) || !errors.Is(err, ErrInvalidValue) {
121			t.Fatalf("err = %v, want ErrInvalidValue", err)
122		}
123		if pe.Name != "port" || pe.Value != "bad" || pe.Source != SourceConfig || pe.Token != "" {
124			t.Fatalf("error fields = %+v", pe)
125		}
126	
127		// Any bad element fails repeatable conversion, carrying that raw value.
128		_, err = p.ParseWithSources([]string{"--need", "x"},
129			map[string][]string{"nums": {"1", "", "3"}}, nil)
130		if !errors.As(err, &pe) || !errors.Is(err, ErrInvalidValue) {
131			t.Fatalf("err = %v, want ErrInvalidValue", err)
132		}
133		if pe.Name != "num" || pe.Value != "" || pe.Source != SourceConfig || pe.Token != "" {
134			t.Fatalf("error fields = %+v", pe)
135		}
136	}
137	
138	func TestEnvironmentSingleValue(t *testing.T) {
139		p := boundParser(t)
140		r, err := p.ParseWithSources([]string{"--need", "x"}, nil,
141			map[string]string{"APP_TAG": "envtag", "APP_VERBOSE": "true"})
142		if err != nil {
143			t.Fatal(err)
144		}
145		if got := r.Strings("tag"); !reflect.DeepEqual(got, []string{"envtag"}) {
146			t.Fatalf("tags = %v, want single environment value", got)
147		}
148		if r.Source("tag") != SourceEnvironment || !r.Bool("verbose") || r.Source("verbose") != SourceEnvironment {
149			t.Fatalf("source = tag:%v verbose:%v", r.Source("tag"), r.Source("verbose"))
150		}
151	}
152	
153	func TestLayersReplaceWholesale(t *testing.T) {
154		p := boundParser(t)
155		config := map[string][]string{"tags": {"cfg-a", "cfg-b"}}
156	
157		// Environment replaces all config values rather than prepending.
158		r, err := p.ParseWithSources([]string{"--need", "x"}, config, map[string]string{"APP_TAG": "env-only"})
159		if err != nil {
160			t.Fatal(err)
161		}
162		if got := r.Strings("tag"); !reflect.DeepEqual(got, []string{"env-only"}) {
163			t.Fatalf("env must replace config wholesale, got %v", got)
164		}
165	
166		// Command line replaces environment wholesale.
167		r, err = p.ParseWithSources([]string{"--tag", "cli", "--need", "x"}, config,
168			map[string]string{"APP_TAG": "env-only"})
169		if err != nil {
170			t.Fatal(err)
171		}
172		if got := r.Strings("tag"); !reflect.DeepEqual(got, []string{"cli"}) {
173			t.Fatalf("cli must replace env wholesale, got %v", got)
174		}
175		if r.Count("tag") != 1 || !r.Provided("tag") {
176			t.Fatal("slice accessor follows layer, but Count must stay command-line-only")
177		}
178	}
179	
180	func TestEmptyValuesAreExplicit(t *testing.T) {
181		p, err := NewParser([]Option{
182			{Long: "s", Type: TypeString, Default: "dflt", ConfigKey: "s", EnvVar: "S"},
183			{Long: "n", Type: TypeInt, ConfigKey: "n", EnvVar: "N"},
184			{Long: "b", Type: TypeBool, ConfigKey: "b", EnvVar: "B"},
185		}, nil)
186		if err != nil {
187			t.Fatal(err)
188		}
189	
190		// Empty environment value is an explicit value per type.
191		r, err := p.ParseWithSources(nil, nil, map[string]string{"S": ""})
192		if err != nil {
193			t.Fatal(err)
194		}
195		if r.String("s") != "" || r.Source("s") != SourceEnvironment {
196			t.Fatalf("empty env string: value=%q source=%v", r.String("s"), r.Source("s"))
197		}
198		for _, key := range []string{"N", "B"} {
199			_, err := p.ParseWithSources(nil, nil, map[string]string{key: ""})
200			var pe *ParseError
201			if !errors.As(err, &pe) || !errors.Is(err, ErrInvalidValue) || pe.Source != SourceEnvironment || pe.Token != "" {
202				t.Fatalf("empty env %s: err = %v, want env invalid-value", key, err)
203			}
204		}
205	
206		// Empty config elements are explicit values too.
207		r, err = p.ParseWithSources(nil, map[string][]string{"s": {""}}, nil)
208		if err != nil {
209			t.Fatal(err)
210		}
211		if r.String("s") != "" || r.Source("s") != SourceConfig {
212			t.Fatalf("empty config element: value=%q source=%v", r.String("s"), r.Source("s"))
213		}
214		_, err = p.ParseWithSources(nil, map[string][]string{"n": {""}}, nil)
215		var pe *ParseError
216		if !errors.As(err, &pe) || !errors.Is(err, ErrInvalidValue) || pe.Source != SourceConfig || pe.Name != "n" {
217			t.Fatalf("empty config int element: err = %v", err)
218		}
219	
220		// A present but empty config slice means "not supplied".
221		r, err = p.ParseWithSources(nil, map[string][]string{"s": {}, "n": {}}, nil)
222		if err != nil {
223			t.Fatal(err)
224		}
225		if r.Source("s") != SourceDefault || r.String("s") != "dflt" {
226			t.Fatalf("empty config slice must fall back to default: source=%v value=%q", r.Source("s"), r.String("s"))
227		}
228		if r.Source("n") != SourceDefault {
229			t.Fatalf("empty config slice: source = %v, want default", r.Source("n"))
230		}
231	}
