448	func TestParseWithSourcesConcurrentUse(t *testing.T) {
449		p := boundParser(t)
450		config := map[string][]string{"tags": {"a", "b"}}
451		environ := map[string]string{"APP_PORT": "7000"}
452	
453		const goroutines = 32
454		const iterations = 100
455		var wg sync.WaitGroup
456		errCh := make(chan error, goroutines)
457		for g := 0; g < goroutines; g++ {
458			wg.Add(1)
459			go func(g int) {
460				defer wg.Done()
461				for i := 0; i < iterations; i++ {
462					args := []string{"--need", fmt.Sprintf("g%d", g), "--tag", "cli"}
463					r, err := p.ParseWithSources(args, config, environ)
464					if err != nil {
465						errCh <- err
466						return
467					}
468					if r.String("need") != fmt.Sprintf("g%d", g) {
469						errCh <- fmt.Errorf("need = %q", r.String("need"))
470						return
471					}
472					if r.Int("port") != 7000 || r.Source("port") != SourceEnvironment {
473						errCh <- fmt.Errorf("port = %d source %v", r.Int("port"), r.Source("port"))
474						return
475					}
476					if got := r.Strings("tag"); !reflect.DeepEqual(got, []string{"cli"}) {
477						errCh <- fmt.Errorf("tags = %v", got)
478						return
479					}
480				}
481			}(g)
482		}
483		wg.Wait()
484		close(errCh)
485		for err := range errCh {
486			t.Fatal(err)
487		}
488		// Shared input survived the storm.
489		if got := config["tags"]; !reflect.DeepEqual(got, []string{"a", "b"}) {
490			t.Fatalf("shared config mutated: %v", got)
491		}
492	}
