5	// This file implements (*Parser).RedactArgs, a logging-oriented
6	// projection of the parser's option grammar: given a raw argument vector
7	// it returns an independent copy whose sensitive values are replaced with
8	// "<redacted>". It recognizes options with the same token-level rules as
9	// Parse, but it performs no validation: unknown options, missing values
10	// and type-incompatible values are never errors and never stop the walk.
11	
12	// redactedMarker replaces every redacted sensitive value, including the
13	// value portion of an attached token.
14	const redactedMarker = "<redacted>"
15	
16	// RedactArgs returns a copy of args in which values belonging to options
17	// declared Sensitive are replaced with "<redacted>". The returned slice is
18	// freshly allocated and neither it nor args is modified, so RedactArgs is
19	// safe to call concurrently on a shared Parser and safe to apply to the
20	// same args Parse is consuming.
21	//
22	// Recognition mirrors Parse up to (but never past) a standalone "--"
23	// token, which is itself retained; tokens at and after it keep their
24	// original bytes and order. For a sensitive non-boolean option:
25	//
26	//   - "--token value" replaces the following token, and every repetition
27	//     is handled ("--token a --token b" -> "--token <redacted> --token
28	//     <redacted>");
29	//   - "--token=value" keeps the option spelling and replaces only the
30	//     text after "=" ("--token=<redacted>");
31	//   - "-tvalue" and "-t=value" keep the preceding short cluster, if any,
32	//     and replace only the attached value ("-vtsecret" -> "-vt<redacted>");
33	//   - "-t value" replaces the following token.
34	//
35	// A sensitive boolean option carries no value: its bare long and short
36	// spellings (including clusters) are left unchanged, and "--flag=value"
37	// masks only the explicit value ("--flag=<redacted>").
38	//
39	// Options not declared sensitive, unknown or incomplete tokens, and
40	// positional arguments are copied byte-for-byte. In particular a known
41	// non-sensitive value-taking option still consumes the following token,
42	// so a value that merely looks like a sensitive option name is never
43	// mistaken for one ("--name --token" keeps "--token" as name's value).
44	// RedactArgs never converts values and reports no error.
45	func (p *Parser) RedactArgs(args []string) []string {
46		out := append([]string(nil), args...)
47	
48		onlyPositional := false
49		for i := 0; i < len(out); i++ {
50			token := out[i]
51			if onlyPositional {
52				continue
53			}
54			if token == "--" {
55				onlyPositional = true
56				continue
57			}
58			switch {
59			case strings.HasPrefix(token, "--"):
60				i = p.redactLong(out, i)
61			case len(token) > 1 && token[0] == '-':
62				i = p.redactShort(out, i)
